import ast
import json
from collections import Counter
def task_func(file_pointer):
    """
    Reads from a given file pointer to a JSON file, evaluates strings that represent 
    dictionaries to actual dictionaries, and counts the frequency of each key 
    across all dictionary entries in the JSON data.

    This function assumes the input JSON data is a list of dictionaries or 
    strings that can be evaluated as dictionaries.

    Args:
        file_pointer: A file-like object containing JSON data.

    Returns:
        collections.Counter: A Counter object representing the frequency of each 
        key found in the dictionaries.
    """
    try:
        # Load the JSON data from the file pointer
        data = json.load(file_pointer)
    except (json.JSONDecodeError, ValueError):
        return Counter()

    # Ensure data is a list as per the assumption
    if not isinstance(data, list):
        return Counter()

    key_counts = Counter()

    for item in data:
        processed_dict = None

        # If the item is already a dictionary
        if isinstance(item, dict):
            processed_dict = item
        # If the item is a string, attempt to evaluate it as a dictionary
        elif isinstance(item, str):
            try:
                evaluated = ast.literal_eval(item)
                if isinstance(evaluated, dict):
                    processed_dict = evaluated
            except (ValueError, SyntaxError):
                # If it's not a valid dictionary string, skip it
                continue

        # If we successfully obtained a dictionary, update the counter with its keys
        if processed_dict is not None:
            key_counts.update(processed_dict.keys())

    return key_counts
